//! Comtech's rate-7/8 turbo product code (its "TPC 7/8", 16K block), as a
//! live Comtech carrier sends it: 171.43 kS/s QPSK at 11 664.53 MHz
//! (Rory's VFO_29 capture, 2026-10-14), every part of it found from the
//! signal — no document was used.
//!
//! A frame is 16 320 bits (8160 QPSK symbols): a 32-bit unique word
//! F8DD4258h, then a (128,120) × (128,120) product codeword of extended
//! Hamming codes, sent row by row. Both component codes are generated by
//! x⁷ + x³ + 1, each word its 120 data bits, 7 Hamming parity bits (highest
//! degree first) and an even overall parity bit. The first row's first 96
//! bits — all data — are shortened away (taken as zeros, not sent), so the
//! block is 128² − 96 = 16 288 bits carrying 120² − 96 = 14 304 data bits.
//! The last 24 of those are overhead (constant on the carrier seen; what
//! they mean is not known); the other 14 280 are the user's data, 7/8 of
//! the frame exactly: on QPSK the data rate is 1.75 × the symbol rate
//! (300 kbit/s at 171.43 kS/s).
//!
//! The code bits are not scrambled. The data are, by the (2, 3, 9, 12)
//! additive sequence of IESS-315 restarted every frame
//! ([`crate::payload::Descrambler::Additive`], `early`); idle, they are
//! HDLC flags. [`crate::tpc2964::TpcRx`] receives it.

use crate::tpc::{ExtHamming, ProductCode};

/// The unique word, 32 bits, sent MSB first.
pub const UW: u32 = 0xF8DD_4258;
pub const UW_LEN: usize = 32;
/// Rows and columns of the product codeword.
pub const SIDE: usize = 128;
/// Data bits of each row or column.
pub const SIDE_DATA: usize = 120;
/// The first row's leading bits not sent.
pub const SHORTENED: usize = 96;
/// Code bits sent a frame (after the UW).
pub const BLOCK: usize = SIDE * SIDE - SHORTENED;
pub const FRAME: usize = UW_LEN + BLOCK;
/// Data bits in the block, and the overhead bits at their end.
pub const BLOCK_DATA: usize = SIDE_DATA * SIDE_DATA - SHORTENED;
pub const OVERHEAD: usize = 24;
/// The user's data bits a frame.
pub const DATA: usize = BLOCK_DATA - OVERHEAD;

/// The Hamming generator x⁷ + x³ + 1 (bit i = x^i).
pub const POLY: u32 = 0x89;

/// The product code, unshortened: the receiver takes the shortened bits as
/// known zeros.
pub fn code() -> ProductCode {
    ProductCode::new(ExtHamming::new(7, POLY, 0), ExtHamming::new(7, POLY, 0))
}

/// Comtech TPC 7/8 transmitter, for tests and test signals: `DATA` user
/// bits and the 24 overhead bits (as given: scramble the data first, if
/// they are to be), out `FRAME` bits (0/1).
pub fn frame(code: &ProductCode, data: &[u8], overhead: u32, out: &mut Vec<u8>) {
    assert_eq!(data.len(), DATA);
    out.extend((0..UW_LEN).map(|i| ((UW >> (UW_LEN - 1 - i)) & 1) as u8));
    let mut all = vec![0u8; SHORTENED];
    all.extend_from_slice(data);
    all.extend((0..OVERHEAD).map(|i| ((overhead >> (OVERHEAD - 1 - i)) & 1) as u8));
    let block = code.encode(&all);
    out.extend_from_slice(&block[SHORTENED..]);
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn sizes() {
        assert_eq!(FRAME, 16_320);
        // Exactly 7/8 of the frame is the user's.
        assert_eq!(DATA * 8, FRAME * 7);
        let c = code();
        assert_eq!((c.n(), c.k()), (SIDE * SIDE, SIDE_DATA * SIDE_DATA));
    }

    /// A row of the live carrier's first frame after its UW (row 1 of the
    /// block), as received: a codeword of the code.
    #[test]
    fn a_live_row_is_a_codeword() {
        let row = "1100010011111000101111001100100101101000101010101001110011110010\
                   1110010001111010000011110011100110001011010101010101011100001011";
        let bits: Vec<u8> = row.bytes().map(|b| b - b'0').collect();
        let h = ExtHamming::new(7, POLY, 0);
        let mut out = vec![0u8; SIDE];
        assert!(h.decode_hard(&bits, &mut out));
        assert_eq!(out, bits);
    }
}
